window.kbPageData["views/entry/k-ad956494f7404c0d"] = {"key":"entry/k-ad956494f7404c0d","state":{"route":"entry/k-ad956494f7404c0d"},"node":{"id":"k-ad956494f7404c0d","mode":"k","title":"单侧差集的最少人数","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["两集合的单侧差集最小量等于该集合数量减去最大交集量"],"qs":["江苏 2023 B类 行测#130"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"只属于集合 A 的人数等于 A 的人数减去两集合的交集人数。若只知道两集合各有多少人，交集最多等于较小集合的人数，因此只属于 A 的人数最少为两集合人数之差与零中的较大值。","review":{"definition":"只属于集合 A 的人数等于 A 的人数减去两集合的交集人数。若只知道两集合各有多少人，交集最多等于较小集合的人数，因此只属于 A 的人数最少为两集合人数之差与零中的较大值。","explanation":"题解给出，2022年1107名受访者中，55.6%有放大字体需求，33.9%有放大图标需求。即使有放大图标需求的人都同时有放大字体需求，仍约有1107×（55.6%－33.9%）≈240人有放大字体需求而没有放大图标需求。两类需求的重叠越少，这部分人数就越多，所以可以推出B项所说的“不少于230人”。","references":[],"evidence":"有放大字体、放大图标需求的受访者的占比分别为55.6%、33.9%。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2023 B类 行测#130":{"paper":"江苏 2023 B类 行测","n":130,"mod":"资料分析","src":["22262c34d18cd68fbee4.pdf",26],"asrc":["b08f2713d73015eac675.pdf",42],"card":"b540c276518a23e684614079","links":[{"id":"k-ad956494f7404c0d","role":"解题依据","why":"较小群体全部落在较大群体内时，交集达到上限，较大群体中只具备该项需求的人数达到下限。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-ad956494f7404c0d":[["江苏 2023 B类 行测#130"]]}};
